// src/utils/mixing.ts
import type { RGB, PaintProfile } from '../config';
import { srgbToLinear, linearToSrgb, rgbToHsl, hslToRgb } from './colorMath';

export function mixLinearRgb(drops: number[], componentsRgb: RGB[]): RGB {
  let total = 0;
  for (let i = 0; i < drops.length; i++) total += drops[i];
  if (total === 0) return [0, 0, 0];

  let lr = 0, lg = 0, lb = 0;
  for (let i = 0; i < drops.length; i++) {
    if (drops[i] <= 0) continue;
    const w = drops[i] / total;
    lr += w * srgbToLinear(componentsRgb[i][0]);
    lg += w * srgbToLinear(componentsRgb[i][1]);
    lb += w * srgbToLinear(componentsRgb[i][2]);
  }

  return [
    Math.round(linearToSrgb(lr) * 255),
    Math.round(linearToSrgb(lg) * 255),
    Math.round(linearToSrgb(lb) * 255),
  ];
}

// ---------------------------------------------------------
// ФИЗИЧЕСКАЯ ФУНКЦИЯ СМЕШИВАНИЯ КРАСОК (Luminance + RYB)
// ---------------------------------------------------------

function getLuminance(r: number, g: number, b: number): number {
  const lr = srgbToLinear(r);
  const lg = srgbToLinear(g);
  const lb = srgbToLinear(b);
  return 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
}

function adjustLuminance(r: number, g: number, b: number, targetY: number): RGB {
  let lr = srgbToLinear(r);
  let lg = srgbToLinear(g);
  let lb = srgbToLinear(b);
  
  let currentY = 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
  if (currentY <= 0.001) return [0, 0, 0];

  if (targetY <= currentY) {
    const scale = targetY / currentY;
    lr *= scale; lg *= scale; lb *= scale;
  } else {
    if (currentY < 1) {
      const amount = (targetY - currentY) / (1 - currentY);
      lr = lr + (1 - lr) * amount;
      lg = lg + (1 - lg) * amount;
      lb = lb + (1 - lb) * amount;
    }
  }

  return [
    Math.max(0, Math.min(255, Math.round(linearToSrgb(lr) * 255))),
    Math.max(0, Math.min(255, Math.round(linearToSrgb(lg) * 255))),
    Math.max(0, Math.min(255, Math.round(linearToSrgb(lb) * 255)))
  ];
}

// ---------------------------------------------------------
// PIGMENT COLOR WHEEL (RYB) MAPPING
// ---------------------------------------------------------
function hueRgbToRyb(h: number): number {
  if (h < 60) return h * 2;
  if (h < 120) return 120 + (h - 60);
  if (h < 240) return 180 + (h - 120) * 0.5;
  return 240 + (h - 240);
}

function hueRybToRgb(h: number): number {
  if (h < 120) return h * 0.5;
  if (h < 180) return 60 + (h - 120);
  if (h < 240) return 120 + (h - 180) * 2;
  return 240 + (h - 240);
}

// ---------------------------------------------------------
// ГЛАВНАЯ ФУНКЦИЯ СМЕШИВАНИЯ КРАСОК (HYBRID LUMINANCE + RYB)
// ---------------------------------------------------------
export function mixKubelkaMunk(drops: number[], componentsRgb: RGB[]): RGB {
  let total = 0;
  for (let i = 0; i < drops.length; i++) total += drops[i];
  if (total === 0) return [0, 0, 0];

  // 1. Физическая Яркость (Субтрактивное геометрическое среднее по Luminance)
  let mixY = 1.0;
  for (let i = 0; i < drops.length; i++) {
    if (drops[i] <= 0) continue;
    const w = drops[i] / total;
    const [r, g, b] = componentsRgb[i];
    // Ограничиваем светимость пигментов от 0.02 (сажа) до 0.98 (титановые белила)
    const Y = Math.max(0.02, Math.min(0.98, getLuminance(r, g, b)));
    mixY *= Math.pow(Y, w);
  }

  // 2. Рассчитываем Оттенок (Hue) и Насыщенность (Saturation) через RYB-векторы
  let sumChromaWeight = 0;
  let sumS = 0;
  let vecX = 0, vecY = 0;
  let sumW = 0;

  for (let i = 0; i < drops.length; i++) {
    if (drops[i] <= 0) continue;
    const w = drops[i] / total;
    const [r, g, b] = componentsRgb[i];
    const [h, s] = rgbToHsl([r, g, b]);
    
    // Взвешиваем насыщенность только по хроматическим компонентам.
    // Белый (S=0) и Черный (S=0) не должны искусственно занижать базовую чистоту цвета (S) в HSL.
    // Их осветляющий/затемняющий эффект физически корректно обрабатывается в adjustLuminance.
    const chromaWeight = w * s;
    sumChromaWeight += chromaWeight;
    sumS += chromaWeight * s;

    const weight = w * s;
    
    if (weight > 0) {
      const rybH = hueRgbToRyb(h);
      const rad = rybH * Math.PI / 180;
      vecX += Math.cos(rad) * weight;
      vecY += Math.sin(rad) * weight;
      sumW += weight;
    }
  }

  if (sumW === 0) {
    // Смесь состоит только из нейтральных цветов (черный, белый, серый)
    return adjustLuminance(128, 128, 128, mixY);
  }

  let finalH_ryb = (Math.atan2(vecY, vecX) * 180 / Math.PI + 360) % 360;
  const finalH = hueRybToRgb(finalH_ryb);
  
  const vecLen = Math.sqrt(vecX * vecX + vecY * vecY);
  const cancellationFactor = vecLen / sumW;
  
  const avgS = sumChromaWeight > 0 ? sumS / sumChromaWeight : 0;
  
  // Сохраняем насыщенность при смешивании соседних оттенков
  const vibrancyPreservation = Math.pow(cancellationFactor, 0.3);
  const finalS = Math.min(1.0, avgS * vibrancyPreservation * 1.2);

  // ГРЯЗЬ: Когда смешиваются противоположные цвета, они поглощают спектры друг друга.
  const mudDrop = 1.0 - (1.0 - cancellationFactor) * 0.85; // Синхронизировано с Rust Wasm Engine
  const finalY = mixY * mudDrop;

  // Создаем базовый цвет 50% яркости и подгоняем его
  const baseColor = hslToRgb(finalH, finalS, 0.5);
  return adjustLuminance(baseColor[0], baseColor[1], baseColor[2], finalY);
}

export interface MixingDNA {
  linearMix: RGB;
  kmMixY: number;
  kmVecX: number;
  kmVecY: number;
  sumW: number;
  cancellationFactor: number;
  vibrancyPreservation: number;
  mudDrop: number;
  finalY: number;
  kmMix: RGB;
  interpolatedBase: RGB;
  impurityDrop: number;
  dirtiedBase: RGB;
  totalAlpha: number;
  finalColor: RGB;
}

export function getMixingDNA(
  drops: number[],
  componentsRgb: RGB[],
  profile: PaintProfile,
  substrateColor: RGB = [255, 255, 255],
  isPuddle: boolean = false
): MixingDNA | null {
  const total = drops.reduce((s, d) => s + d, 0);
  if (total === 0) return null;

  const linearMix = mixLinearRgb(drops, componentsRgb);

  // Re-calculating KubelkaMunk to capture intermediate vars
  let mixY = 1.0;
  for (let i = 0; i < drops.length; i++) {
    if (drops[i] <= 0) continue;
    const w = drops[i] / total;
    const [r, g, b] = componentsRgb[i];
    const Y = Math.max(0.02, Math.min(0.98, getLuminance(r, g, b)));
    mixY *= Math.pow(Y, w);
  }

  let sumChromaWeight = 0, sumS = 0, vecX = 0, vecY = 0, sumW = 0;
  for (let i = 0; i < drops.length; i++) {
    if (drops[i] <= 0) continue;
    const w = drops[i] / total;
    const [r, g, b] = componentsRgb[i];
    const [h, s] = rgbToHsl([r, g, b]);
    
    const chromaWeight = w * s;
    sumChromaWeight += chromaWeight;
    sumS += chromaWeight * s;
    
    const weight = w * s; 
    if (weight > 0) {
      const rybH = hueRgbToRyb(h);
      const rad = rybH * Math.PI / 180;
      vecX += Math.cos(rad) * weight;
      vecY += Math.sin(rad) * weight;
      sumW += weight;
    }
  }

  let kmMix: RGB = [0, 0, 0];
  let cancellationFactor = 0, vibrancyPreservation = 0, mudDrop = 1.0, finalY = mixY;

  if (sumW === 0) {
    kmMix = adjustLuminance(128, 128, 128, mixY);
  } else {
    let finalH_ryb = (Math.atan2(vecY, vecX) * 180 / Math.PI + 360) % 360;
    const finalH = hueRybToRgb(finalH_ryb);
    const vecLen = Math.sqrt(vecX * vecX + vecY * vecY);
    cancellationFactor = vecLen / sumW;
    vibrancyPreservation = Math.pow(cancellationFactor, 0.3);
    const avgS = sumChromaWeight > 0 ? sumS / sumChromaWeight : 0;
    // * 1.2 — как в рабочем mixKubelkaMunk и Rust-движке. Раньше здесь множителя
    // не было, из-за чего диагностический разбор давал цвет иной, чем реальная смесь.
    const finalS = Math.min(1.0, avgS * vibrancyPreservation * 1.2);
    mudDrop = 1.0 - (1.0 - cancellationFactor) * 0.85;
    finalY = mixY * mudDrop;
    const baseColor = hslToRgb(finalH, finalS, 0.5);
    kmMix = adjustLuminance(baseColor[0], baseColor[1], baseColor[2], finalY);
  }

  const w = profile.kmWeight;
  let lr = srgbToLinear(linearMix[0]) * (1 - w) + srgbToLinear(kmMix[0]) * w;
  let lg = srgbToLinear(linearMix[1]) * (1 - w) + srgbToLinear(kmMix[1]) * w;
  let lb = srgbToLinear(linearMix[2]) * (1 - w) + srgbToLinear(kmMix[2]) * w;

  const interpolatedBase: RGB = [
    Math.round(linearToSrgb(lr) * 255),
    Math.round(linearToSrgb(lg) * 255),
    Math.round(linearToSrgb(lb) * 255)
  ];

  const numColors = drops.filter(d => d > 0).length;
  let impurityDrop = 1.0;
  if (numColors > 2 && profile.darkeningFactor > 0) {
    impurityDrop = Math.pow(1 - profile.darkeningFactor, numColors - 2);
    lr *= impurityDrop;
    lg *= impurityDrop;
    lb *= impurityDrop;
  }
  
  const dirtiedBase: RGB = [
    Math.round(linearToSrgb(lr) * 255),
    Math.round(linearToSrgb(lg) * 255),
    Math.round(linearToSrgb(lb) * 255)
  ];

  const power = Math.max(2, total) * 1.5; // мин. укрывистость = «2 капли» (см. mixColors)
  const totalAlpha = isPuddle ? 1.0 : 1 - Math.pow(profile.transparency, power);

  const subLr = srgbToLinear(substrateColor[0]);
  const subLg = srgbToLinear(substrateColor[1]);
  const subLb = srgbToLinear(substrateColor[2]);

  lr = lr * totalAlpha + subLr * (1 - totalAlpha);
  lg = lg * totalAlpha + subLg * (1 - totalAlpha);
  lb = lb * totalAlpha + subLb * (1 - totalAlpha);

  let finalColor: RGB = [
    Math.round(linearToSrgb(lr) * 255),
    Math.round(linearToSrgb(lg) * 255),
    Math.round(linearToSrgb(lb) * 255)
  ];

  return {
    linearMix,
    kmMixY: mixY,
    kmVecX: vecX,
    kmVecY: vecY,
    sumW,
    cancellationFactor,
    vibrancyPreservation,
    mudDrop,
    finalY,
    kmMix,
    interpolatedBase,
    impurityDrop,
    dirtiedBase,
    totalAlpha,
    finalColor
  };
}

export function mixColors(
  drops: number[],
  componentsRgb: RGB[],
  profile: PaintProfile,
  substrateColor: RGB = [255, 255, 255],
  isPuddle: boolean = false
): RGB {
  const totalDrops = drops.reduce((s, d) => s + d, 0);
  if (totalDrops === 0) return [0, 0, 0];

  // 1. Оптическое смешивание (Свет / Linear RGB)
  const linearMix = mixLinearRgb(drops, componentsRgb);

  // Проверяем, сколько уникальных цветов реально используется
  const activeIndices: number[] = [];
  for (let i = 0; i < drops.length; i++) {
    if (drops[i] > 0) activeIndices.push(i);
  }

  let lr, lg, lb;

  // Если используется только один цвет, нет смысла смешивать его по физическим законам, 
  // избегаем искажения яркости и насыщенности.
  if (activeIndices.length === 1) {
    const idx = activeIndices[0];
    lr = srgbToLinear(componentsRgb[idx][0]);
    lg = srgbToLinear(componentsRgb[idx][1]);
    lb = srgbToLinear(componentsRgb[idx][2]);
  } else {
    // 2. Физическое смешивание (Пигменты / Kubelka-Munk + RYB)
    const kmMix = mixKubelkaMunk(drops, componentsRgb);

    // 3. Интерполяция по свойству краски (kmWeight)
    // Выполняется в линейном пространстве для соблюдения законов сохранения энергии
    const w = profile.kmWeight;
    lr = srgbToLinear(linearMix[0]) * (1 - w) + srgbToLinear(kmMix[0]) * w;
    lg = srgbToLinear(linearMix[1]) * (1 - w) + srgbToLinear(kmMix[1]) * w;
    lb = srgbToLinear(linearMix[2]) * (1 - w) + srgbToLinear(kmMix[2]) * w;
  }

  // 4. Экспоненциальное затемнение от смешивания множества пигментов (Эффект грязной кисти)
  // Применяется к САМОЙ КРАСКЕ до того, как она легла на бумагу.
  // Загрязнение пигмента линейно снижает его отражательную способность!
  const numColors = drops.filter(d => d > 0).length;
  if (numColors > 2 && profile.darkeningFactor > 0) {
    const impurityDrop = Math.pow(1 - profile.darkeningFactor, numColors - 2);
    lr *= impurityDrop;
    lg *= impurityDrop;
    lb *= impurityDrop;
  }

  // 5. Физически точная прозрачность (Alpha Compositing)
  // В лужице (на палитре) краска всегда непрозрачная. На бумаге - согласно профилю.
  // Минимальная укрывистость = «2 капли»: одиночный мазок уже укрывист, а не
  // полупрозрачен. Иначе чистый непрозрачный цвет (#000000 и т.п.) при 1 части
  // просвечивал бумагой → солвер предлагал 2 части. Смеси (≥2) не меняются.
  const power = Math.max(2, totalDrops) * 1.5;
  const totalAlpha = isPuddle ? 1.0 : 1 - Math.pow(profile.transparency, power);

  // 6. Взаимодействие с подложкой (Поверхностью) - Идеальное смешивание в Linear RGB
  const subLr = srgbToLinear(substrateColor[0]);
  const subLg = srgbToLinear(substrateColor[1]);
  const subLb = srgbToLinear(substrateColor[2]);

  lr = lr * totalAlpha + subLr * (1 - totalAlpha);
  lg = lg * totalAlpha + subLg * (1 - totalAlpha);
  lb = lb * totalAlpha + subLb * (1 - totalAlpha);

  return [
    Math.round(linearToSrgb(lr) * 255),
    Math.round(linearToSrgb(lg) * 255),
    Math.round(linearToSrgb(lb) * 255),
  ];
}

// Смешивание ДВУХ уже готовых цветов красок на холсте (wet-on-wet) по той же
// СУБТРАКТИВНОЙ модели, что и рецепты в лунках: синий+жёлтый дают зелёный,
// а не грязно-серое (как получалось при перцептивном RMS-блендинге).
// isPuddle=true — краска на палитре/холсте непрозрачна (без подложки).
export function blendTwoPaints(c1: RGB, c2: RGB, w: number, profile: PaintProfile): RGB {
  const ww = Math.max(0, Math.min(1, Number.isFinite(w) ? w : 0));
  if (ww <= 0.0005) return c1;      // под кистью нет мокрой краски — быстрый путь
  if (ww >= 0.9995) return c2;
  return mixColors([1 - ww, ww], [c1, c2], profile, [255, 255, 255], true);
}

// Перцептивный кроссфейд ОДНОГО И ТОГО ЖЕ пигмента между «мокрым» и «сухим»
// видом (не смешивание разных красок!). Делаем в линейном свете — без RMS-
// артефактов и потемнения наивного sRGB-усреднения.
export function lerpRgbLinear(c1: RGB, c2: RGB, w: number): RGB {
  const ww = Math.max(0, Math.min(1, Number.isFinite(w) ? w : 0));
  return [
    Math.round(linearToSrgb(srgbToLinear(c1[0]) * (1 - ww) + srgbToLinear(c2[0]) * ww) * 255),
    Math.round(linearToSrgb(srgbToLinear(c1[1]) * (1 - ww) + srgbToLinear(c2[1]) * ww) * 255),
    Math.round(linearToSrgb(srgbToLinear(c1[2]) * (1 - ww) + srgbToLinear(c2[2]) * ww) * 255),
  ];
}
